import copy,json,pathlib,hashlib
out=pathlib.Path(__file__).parent
base={'schema':'kernel-report-training/v1','synthetic':True,'version':{'origin':'kernel.org','id':'6.12.4','recent_check':True},'description':'In the local ACL toy an unrelated actor reads the training record. No actual kernel claim.','conditions':{'configuration':'toy-only','permission':'ordinary-actor'},'reproducer':{'format':'instructions','trigger':'read-training-record','confirm':'access-granted','trace_id':'independent-a'},'traces':[{'id':'independent-a','version':'6.12.4','conditions':{'configuration':'toy-only','permission':'ordinary-actor'},'trigger':'read-training-record','observation':'access-granted','reproduced':True,'operation':'read-training-record','permitted':True,'production':True,'specimen':{'actor':'visitor','owner':'custodian','mode':'buggy'}}],'boundary_claim':{'operation':'read-training-record','permitted':False},'ai_assisted':True,'public_text':[{'kind':'summary','text':'Synthetic case, human checked.'},{'kind':'availability','text':'Reproducer available privately on request.'}]}
cases=[]
def add(name,change=None,e='corroborated-synthetic',b='supported-synthetic',d='public-status-only',rc=0):
 x=copy.deepcopy(base)
 if change: change(x)
 cases.append({'id':name,'input':x,'expected':{'evidence':e,'boundary':b,'disclosure':d,'exit':rc}})
def tr(x,**kw):x['traces'][0].update(kw)
add('actual-unprivileged-toy-crossing')
add('forged-success-fixed-mode',lambda x:x['traces'][0]['specimen'].update(mode='fixed'),e='needs-evidence',b='unestablished')
add('irrelevant-trace-operation',lambda x:tr(x,operation='print-banner'),e='needs-evidence',b='unestablished')
add('unrelated-confirmation',lambda x:(x['reproducer'].update(confirm='a benign banner'),tr(x,observation='a benign banner')),e='needs-evidence',b='unestablished')
add('trace-for-other-version',lambda x:tr(x,version='6.12.3'),e='needs-evidence',b='unestablished')
add('missing-recent-upstream-check',lambda x:x['version'].update(recent_check=False),e='needs-evidence',b='unestablished')
add('moving-version-label',lambda x:(x['version'].update(id='latest mainline'),tr(x,version='latest mainline')),e='needs-evidence',b='unestablished')
add('distribution-origin',lambda x:x['version'].update(origin='distribution'),e='needs-evidence',b='unestablished')
add('condition-conflict',lambda x:tr(x,conditions={'configuration':'different','permission':'ordinary-actor'}),e='needs-evidence',b='unestablished')
add('trigger-conflict',lambda x:tr(x,trigger='noop'),e='needs-evidence',b='unestablished')
add('unselected-good-trace',lambda x:x['reproducer'].update(trace_id='nonexistent'),e='needs-evidence',b='unestablished')
add('reproduction-disclaimed',lambda x:tr(x,reproduced=False),e='needs-evidence',b='unestablished')
add('boolean-corroboration-without-specimen',lambda x:(x['traces'][0].pop('specimen'),x.update(corroborated=True)),e='needs-evidence',b='unestablished')
add('binary-only',lambda x:x['reproducer'].update(format='binary'),e='needs-evidence',b='unestablished')
add('no-confirmation',lambda x:x['reproducer'].update(confirm=''),e='needs-evidence',b='unestablished')
add('authorized-owner-no-crossing',lambda x:(x['traces'][0]['specimen'].update(actor='custodian'),x['boundary_claim'].update(permitted=True)),b='not-supported')
add('false-owner-authority-claim',lambda x:x['traces'][0]['specimen'].update(actor='custodian'),e=['needs-evidence','corroborated-synthetic'],b=['not-supported','unestablished'])
add('revoked-production-assumption',lambda x:tr(x,production=False),b='not-supported')
add('fixed-denies-crossing',lambda x:(x['traces'][0]['specimen'].update(mode='fixed'),tr(x,permitted=False,observation='access-denied'),x['reproducer'].update(confirm='access-denied')),b='not-supported')
add('unobserved-impact-operation',lambda x:x['boundary_claim'].update(operation='gain-root'),b=['not-supported','unestablished'])
add('ai-human-verification-does-not-erase-origin',lambda x:x.update(human_verified=True))
add('ai-public-reproducer',lambda x:x['public_text'].append({'kind':'reproducer','text':'Harmless toy reproduction description'}),d='withhold-reproducer')
add('ai-needs-availability',lambda x:x.update(public_text=[{'kind':'summary','text':'Synthetic report only'}]),d='needs-availability-statement')
add('non-ai-no-confidentiality-inference',lambda x:x.update(ai_assisted=False),d='not-assessed')
add('ai-handling-orthogonal-to-bad-evidence',lambda x:(x['version'].update(recent_check=False),x['public_text'].append({'kind':'reproducer','text':'Toy steps'})),e='needs-evidence',b='unestablished',d='withhold-reproducer')
add('different-policy-schema',lambda x:x.update(schema='other-project-report/v1'),e=['invalid','unsupported','could-not-evaluate'],b=None,d=None,rc=2)
add('real-kernel-input-refused',lambda x:x.update(synthetic=False),e=['invalid','unsupported','could-not-evaluate'],b=None,d=None,rc=2)
add('duplicate-trace-id',lambda x:x['traces'].append(copy.deepcopy(x['traces'][0])),e='invalid',b=None,d=None,rc=2)
add('bad-specimen-type',lambda x:x['traces'][0].update(specimen=[]),e='invalid',b=None,d=None,rc=2)
add('unknown-toy-mode',lambda x:x['traces'][0]['specimen'].update(mode='unrecognized'),e='needs-evidence',b='unestablished')
p=out/'cases.json';p.write_text(json.dumps(cases,indent=2)+'\n');print(len(cases),hashlib.sha256(p.read_bytes()).hexdigest())
